custom_css:
/*
* ==========================================
* 主题名称：春和景明
* 美化作者：Belle/贝
* 主题简介：一款极具古风意境的深度美化主题。包含了信笺竖排、长卷画轴背景、瓷白毛玻璃材质、定制提示词（画船听雨眠）、定制思维链（思忖中）以及专属的全屏加载动画等元素。(参考了lc教程贴和墨千尾老师的拼好码css，会在下方一一标注，没标的就是和ai唠嗑出来的，感谢所有分享教程的老师，禁止商用二传，自用二改不可以删除标注)
* ==========================================
*/

/* ===== 一、全局字体与样式重置 ===== */
/* 引入专属字体库：特定提示词与全局默认字体 */
@import url("https://fontsapi.zeoseven.com/445/main/result.css"); /* YFJLXS - 仅限特定提示词(画船听雨眠/思忖中) */
@import url("https://fontsapi.zeoseven.com/582/main/result.css"); /* gkai00mp - 全局默认 */

/* 设置全局默认字体 */
body {
    font-family: "gkai00mp", sans-serif !important;
    font-weight: normal !important;
}

/* 强制所有下拉框、输入框、按钮等表单元素继承全局古风字体 */
input, select, textarea, button, optgroup, option, 
.select2-container, .select2-selection, .select2-selection__rendered, .select2-results__option,
.text_pole {
    font-family: "gkai00mp", sans-serif !important;
}


/* ===== 二、全局页面背景 ===== */
/* 为各个面板展开后的底图设置背景 */
#top-settings-holder .drawer-content,
#right-nav-panel {
    background-image: url('https://i.postimg.cc/jjQhTM7r/c227399dfedfcb0a0701818398a344c3.jpg') !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
}


/* ===== 三、顶栏与菜单美化 (Top Bar) ===== */
/* --- 1. 顶栏底层清洗与透明化（彻底解决右侧白块遮挡背景） --- */
#top-bar, 
#top-bar::before,
#top-bar::after,
#top-settings-holder,
#top-bar-bg,
#top-settings-holder .drawer-toggle,
#top-settings-holder .drawer-header,
#rightNavHolder,
#rightNavHolder .drawer-toggle,
#rightNavHolder .drawer-header,
#unimportantYes {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    border: none !important;
    border-radius: 0 !important;  
    overflow: visible !important; 
    clip-path: none !important;   
}

/* 彻底隐藏顶栏原生的底层背景板 */
#top-bar-bg {
    display: none !important;
    opacity: 0 !important;
}

/* --- 2. 顶栏长背景贴图 --- */
/* 用伪元素创建顶部对齐、100%宽的贴图，向下溢出 */
#top-settings-holder::before {
    content: "" !important;
    position: fixed !important;  
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;     
    height: 100vh !important;    
    background-image: url('https://i.postimg.cc/3Rm7MPsp/IMG-1229.png') !important;
    background-color: transparent !important;
    background-size: 100% auto !important; 
    background-position: top center !important; 
    background-repeat: no-repeat !important; 
    pointer-events: none !important; 
    z-index: 0 !important; 
    border-radius: 0 !important; 
}

/* 确保顶栏的按钮在贴图之上 */
#top-settings-holder .drawer {
    position: relative !important;
    z-index: 10 !important;
}

/* --- 3. 顶栏原生图标抹除与自定义替换 --- */
/* 清洗原生图标及自带滤镜 */
#top-settings-holder .drawer-icon,
#top-bar .menu_button,
#top-bar .drawer-icon {
    color: transparent !important;
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

/* 隐藏原生图标的内部元素和伪元素 */
#top-settings-holder .drawer-icon *,
#top-settings-holder .drawer-icon::before,
#top-settings-holder .drawer-icon::after,
#top-bar .menu_button *,
#top-bar .menu_button::before,
#top-bar .menu_button::after,
#top-bar .drawer-icon *,
#top-bar .drawer-icon::before,
#top-bar .drawer-icon::after {
    display: none !important;
    content: none !important;
    opacity: 0 !important;
    color: transparent !important;
}

/* 将折叠/展开箭头替换为桃花贴图--参考了墨千尾老师的图标平滑过渡，不过只肘出来顶栏，其他的失败了 */
.inline-drawer-icon.fa-circle-chevron-down,
.inline-drawer-icon.down,
.fa-circle-chevron-down,
.inline-drawer-icon.fa-circle-chevron-up,
.inline-drawer-icon.up,
.fa-circle-chevron-up {
    color: transparent !important; 
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-size: 70% !important; 
    padding: 6px !important;  
    margin: -6px !important;  
    background-color: transparent !important; 
    border: none !important;
    box-shadow: none !important;
    text-shadow: none !important;
    -webkit-box-shadow: none !important;
    filter: none !important; 
    -webkit-filter: none !important;
    opacity: 1 !important;
    mask-image: none !important;
    -webkit-mask-image: none !important;
}
/* 折叠状态 */
.inline-drawer-icon.fa-circle-chevron-down,
.inline-drawer-icon.down,
.fa-circle-chevron-down {
    background-image: url('https://i.postimg.cc/cCXxNGsp/IMG-1220.png') !important;
}
/* 展开状态 */
.inline-drawer-icon.fa-circle-chevron-up,
.inline-drawer-icon.up,
.fa-circle-chevron-up {
    background-image: url('https://i.postimg.cc/qBLMKy83/IMG-1221.png') !important;
}

/* 清除鼠标交互时的效果，防白块闪烁(这里唠嗑半天也没效果，但能跑就不动) */
.inline-drawer-icon.fa-circle-chevron-down:hover,
.inline-drawer-icon.down:hover,
.fa-circle-chevron-down:hover,
.inline-drawer-icon.fa-circle-chevron-up:hover,
.inline-drawer-icon.up:hover,
.fa-circle-chevron-up:hover,
.inline-drawer-icon.fa-circle-chevron-down:active,
.inline-drawer-icon.down:active,
.fa-circle-chevron-down:active,
.inline-drawer-icon.fa-circle-chevron-up:active,
.inline-drawer-icon.up:active,
.fa-circle-chevron-up:active,
.inline-drawer-icon.fa-circle-chevron-down:focus,
.inline-drawer-icon.down:focus,
.fa-circle-chevron-down:focus,
.inline-drawer-icon.fa-circle-chevron-up:focus,
.inline-drawer-icon.up:focus,
.fa-circle-chevron-up:focus {
    background-color: transparent !important;
    filter: none !important;
    -webkit-filter: none !important;
    color: transparent !important;
    box-shadow: none !important;
    text-shadow: none !important;
    -webkit-box-shadow: none !important;
    outline: none !important;
    opacity: 1 !important;
    mask-image: none !important;
    -webkit-mask-image: none !important;
}

/* --- 4. 顶栏九大菜单展开图标显隐逻辑 --- */
/* 预留点击展示空间 */
#top-settings-holder .drawer-icon,
#top-bar .drawer-icon {
    min-width: 32px !important;
    min-height: 32px !important;
    transition: background-image 0.2s ease, opacity 0.2s ease !important;
}

/* 面板展开（openIcon）时，显示贴图并开启防遮罩护盾 */
#top-settings-holder .drawer-icon.openIcon,
#top-bar .drawer-icon.openIcon,
#top-settings-holder .drawer-icon.openIcon:hover,
#top-settings-holder .drawer-icon.openIcon:active,
#top-settings-holder .drawer-icon.openIcon:focus,
#top-bar .drawer-icon.openIcon:hover,
#top-bar .drawer-icon.openIcon:active,
#top-bar .drawer-icon.openIcon:focus {
    background-image: url('https://i.postimg.cc/XY7b7n1x/IMG-1205.png') !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    opacity: 1 !important;
    mask-image: none !important;
    -webkit-mask-image: none !important;
    filter: none !important;
    overflow: visible !important;
}


/* ===== 四、各类弹出面板、选择框与输入框美化 ===== */
/* --- 1. 下拉菜单内：折叠面板标题/条目框美化 --- */
.dropdown-menu .inline-drawer-toggle,
.dropdown-menu .inline-drawer-header,
.dropdown-menu .standoutHeader,
.dropdown-content .inline-drawer-toggle,
.dropdown-content .inline-drawer-header,
.dropdown-content .standoutHeader,
#top-settings-holder .inline-drawer-toggle,
#top-settings-holder .inline-drawer-header,
#top-settings-holder .standoutHeader {
    font-weight: normal !important; 
    border: 1px solid #84968c !important; 
    background-color: rgba(255, 255, 255, 0.2) !important;
    background-image: none !important; 
    color: rgba(60, 40, 40, 1) !important; 
    border-radius: 6px !important;
    margin-bottom: 4px !important; 
    backdrop-filter: blur(4px) !important;
    -webkit-backdrop-filter: blur(4px) !important;
}

.dropdown-menu .inline-drawer-toggle:hover,
.dropdown-menu .inline-drawer-header:hover,
.dropdown-menu .standoutHeader:hover,
.dropdown-content .inline-drawer-toggle:hover,
.dropdown-content .inline-drawer-header:hover,
.dropdown-content .standoutHeader:hover,
#top-settings-holder .inline-drawer-toggle:hover,
#top-settings-holder .inline-drawer-header:hover,
#top-settings-holder .standoutHeader:hover {
    background-color: rgba(255, 255, 255, 0.3) !important;
    border-color: #72857a !important; 
}

/* --- 2. 顶栏下拉框内：所有可填写文本框（Input/Textarea）美化 --- */
.dropdown-menu input[type="text"],
.dropdown-menu input[type="password"],
.dropdown-menu input[type="number"],
.dropdown-menu textarea,
.dropdown-menu .text_pole,
.dropdown-content input[type="text"],
.dropdown-content input[type="password"],
.dropdown-content input[type="number"],
.dropdown-content textarea,
.dropdown-content .text_pole,
#top-settings-holder input[type="text"],
#top-settings-holder input[type="password"],
#top-settings-holder input[type="number"],
#top-settings-holder textarea,
#top-settings-holder .text_pole,
#top-settings-holder #firstmessage_textarea,
.select2-search__field,
.wide_textarea {
    background: linear-gradient(to right, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 0) 100%) !important;
    color: rgba(60, 40, 40, 1) !important;
    background-color: transparent !important; 
    border: 1px solid rgba(132, 150, 140, 0.4) !important;
    border-radius: 4px !important;
    padding: 4px 8px !important;
}

.dropdown-menu input::placeholder,
.dropdown-menu textarea::placeholder,
.dropdown-content input::placeholder,
.dropdown-content textarea::placeholder,
#top-settings-holder input::placeholder,
#top-settings-holder textarea::placeholder,
.select2-selection__placeholder {
    color: rgba(60, 40, 40, 0.5) !important;
}

.dropdown-menu input:focus,
.dropdown-menu textarea:focus,
.dropdown-content input:focus,
.dropdown-content textarea:focus,
#top-settings-holder input:focus,
#top-settings-holder textarea:focus,
#top-settings-holder #firstmessage_textarea:focus,
.select2-search__field:focus,
.wide_textarea:focus {
    background: linear-gradient(to right, rgba(255, 255, 255, 1) 0%, rgba(255, 255, 255, 0.2) 100%) !important;
    border-color: #5c8965 !important; 
    outline: none !important; 
}

/* --- 3. 所有灰色区块/标题栏统一风格 --- */
#top-settings-holder .title_restorable,
#top-settings-holder #openai_reasoning_effort,
#top-settings-holder .list-group-item,
#top-settings-holder .prompt-item,
#top-settings-holder .prompt-manager-item,
#top-settings-holder .sysprompt-item,
#top-settings-holder #openai_inline_image_quality,
#top-settings-holder #openai_verbosity,
#top-settings-holder #openai_logit_bias_preset,
#top-settings-holder #main_api,
#top-settings-holder #chat_completion_source,
#top-settings-holder #themes,
#top-settings-holder #tag_import_setting,
#top-settings-holder #aux_field,
#top-settings-holder #example_messages_behavior,
#top-settings-holder #send_on_enter,
#top-settings-holder #image_overswipe,
#top-settings-holder #movingUIPresets,
#top-settings-holder #persona_sort_order,
#top-settings-holder .J-paginationjs-size-select,
#top-settings-holder #persona_description_position,
#top-settings-holder .inline-drawer-content,
#top-settings-holder .select2-selection,
#top-settings-holder h3:not(.inline-drawer-header):not(.inline-drawer-toggle):not(.standoutHeader),
#top-settings-holder h4:not(.inline-drawer-header):not(.inline-drawer-toggle):not(.standoutHeader),
#top-settings-holder .settings-header:not(.inline-drawer-header) {
    background: linear-gradient(to right, rgba(255, 255, 255, 0.75) 0%, rgba(255, 255, 255, 0) 100%) !important;
    background-color: transparent !important; 
    background-image: linear-gradient(to right, rgba(255, 255, 255, 0.75) 0%, rgba(255, 255, 255, 0) 100%) !important; 
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
    border: 1px solid rgba(132, 150, 140, 0.4) !important;
    border-radius: 6px !important;
    padding: 6px 10px !important; 
}

#top-settings-holder .title_restorable:hover,
#top-settings-holder #openai_reasoning_effort:hover,
#top-settings-holder .list-group-item:hover,
#top-settings-holder #openai_inline_image_quality:hover,
#top-settings-holder #openai_verbosity:hover,
#top-settings-holder #openai_logit_bias_preset:hover,
#top-settings-holder #main_api:hover,
#top-settings-holder #chat_completion_source:hover,
#top-settings-holder #themes:hover,
#top-settings-holder #tag_import_setting:hover,
#top-settings-holder #aux_field:hover,
#top-settings-holder #example_messages_behavior:hover,
#top-settings-holder #send_on_enter:hover,
#top-settings-holder #image_overswipe:hover,
#top-settings-holder #movingUIPresets:hover,
#top-settings-holder #persona_sort_order:hover,
#top-settings-holder .J-paginationjs-size-select:hover,
#top-settings-holder #persona_description_position:hover,
#top-settings-holder .inline-drawer-content:hover,
#top-settings-holder .select2-selection:hover,
#top-settings-holder h3:not(.inline-drawer-header):not(.inline-drawer-toggle):not(.standoutHeader):hover,
#top-settings-holder h4:not(.inline-drawer-header):not(.inline-drawer-toggle):not(.standoutHeader):hover,
#top-settings-holder .settings-header:not(.inline-drawer-header):hover {
    background: linear-gradient(to right, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0.1) 100%) !important;
    background-image: linear-gradient(to right, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0.1) 100%) !important;
    border-color: #72857a !important; 
}

/* --- 4. 弹出大底板（下拉菜单、弹窗等） --- */
.dropdown-menu,
.dropdown-content,
.select2-container--default .select2-dropdown,
.select2-dropdown,
.ui-menu.ui-widget,
.popup-content,
.popup-body,
.dialogue_popup,
#character_popup,
#shadow_popup {
    background-color: rgba(245, 246, 245, 0.95) !important; 
    background-image: none !important; 
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border: 1px solid rgba(132, 150, 140, 0.6) !important;
    border-radius: 6px !important;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15) !important; 
}

#options .options-content,
#extensionsMenu {
    background: linear-gradient(to right, rgba(250, 252, 255, 0.9) 0%, rgba(250, 252, 255, 0.3) 100%) !important;
    background-color: transparent !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border: 1px solid rgba(255, 255, 255, 0.8) !important;
    border-radius: 12px !important;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08) !important;
}

/* 剥离父级多余背景，防止滤镜和边框双重叠加 */
#options {
    background: transparent !important;
    border: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
}

option {
    background-color: rgba(245, 246, 245, 0.95) !important;
    color: rgba(60, 40, 40, 1) !important;
}

.select2-results__option,
.ui-menu-item-wrapper {
    color: rgba(60, 40, 40, 1) !important;
    background-color: transparent !important;
}

.select2-results__option--highlighted[aria-selected],
.select2-results__option:hover,
.ui-menu-item-wrapper:hover,
.ui-state-active {
    background-color: rgba(132, 150, 140, 0.3) !important;
    color: rgba(60, 40, 40, 1) !important;
}

/* --- 5. 列表文字颜色与特殊图标(星号、大头针等) --- */
.list-group-item:not(.active),
.list-group-item.inactive,
.list-group-item.disabled,
.prompt-item:not(.active),
.prompt-manager-item:not(.active),
.prompt-manager-inspect-action {
    color: #4a6b58 !important; 
    opacity: 1 !important; 
}
.list-group-item:not(.active) span,
.list-group-item:not(.active) div,
.list-group-item:not(.active) i,
.list-group-item:not(.active) small,
.prompt-item:not(.active) span,
.prompt-item:not(.active) div,
.prompt-item:not(.active) i {
    color: #4a6b58 !important;
    opacity: 1 !important;
}
.list-group-item:not(.active):hover,
.prompt-item:not(.active):hover {
    color: #2e4538 !important; 
}
.list-group-item:not(.active):hover span,
.list-group-item:not(.active):hover div,
.list-group-item:not(.active):hover i,
.list-group-item:not(.active):hover small {
    color: #2e4538 !important; 
}

.prompt-manager-item i.fa-asterisk,
.prompt-item i.fa-asterisk,
.list-group-item i.fa-asterisk,
.fa-fw.fa-solid.fa-asterisk {
    color: #b35c6e !important;
    opacity: 1 !important;
    filter: none !important;
    -webkit-filter: none !important;
    text-shadow: none !important;
}

i.fa-asterisk, i.fa-star, i.fa-thumb-tack, i.fa-square-poll-horizontal, i.fa-syringe,
.fa-fw.fa-solid.fa-asterisk, .fa-fw.fa-solid.fa-star, .fa-fw.fa-solid.fa-thumb-tack,
.fa-fw.fa-solid.fa-square-poll-horizontal, .fa-fw.fa-solid.fa-syringe,
.prompt-manager-item .fa-fw, .prompt-item .fa-fw, .list-group-item .fa-fw {
    color: #d8a4ad !important;
    opacity: 1 !important;
    filter: none !important;
    -webkit-filter: none !important;
    text-shadow: none !important;
    transition: all 0.2s ease; 
}

.list-group-item:not(.active) i.fa-asterisk,
.list-group-item:not(.active) i.fa-star,
.list-group-item:not(.active) i.fa-thumb-tack,
.list-group-item:not(.active) i.fa-square-poll-horizontal,
.list-group-item:not(.active) i.fa-syringe,
.list-group-item:not(.active) .fa-fw,
.prompt-manager-item:not(.active) .fa-fw,
.prompt-item:not(.active) .fa-fw {
    color: #d8a4ad !important;
    opacity: 1 !important;
}

i.fa-asterisk:hover, i.fa-star:hover, i.fa-thumb-tack:hover,
i.fa-square-poll-horizontal:hover, i.fa-syringe:hover,
.prompt-manager-item .fa-fw:hover, .prompt-item .fa-fw:hover, .list-group-item .fa-fw:hover {
    color: #c98a96 !important;
    transform: scale(1.15); 
    cursor: pointer;
}


/* ===== 五、滑动条与滚动条美化 ===== 参考墨千尾老师通用滚动条美化和nakari老师的滑动条代码，才发现老师整理了详细完善的页面美化，我还在一个个的肘，下次试试*/
/* --- 1. 滑动条无畸变还原 --- */
input[type="range"].neo-range-slider,
input[type="range"],
.neo-range-slider {
    --thumb-size: 24px; 
    height: auto !important; 
    background: transparent !important; 
    opacity: 1 !important; 
    filter: none !important; 
    -webkit-filter: none !important;
}

/* Webkit 滑块手柄 */
input[type="range"]::-webkit-slider-thumb,
.neo-range-slider::-webkit-slider-thumb,
.neo-range-slider .thumb {
    width: var(--thumb-size) !important;
    height: var(--thumb-size) !important;
    background-image: url('https://i.postimg.cc/cCXxNGsp/IMG-1220.png') !important;
    background-color: transparent !important; 
    background-size: contain !important; 
    background-repeat: no-repeat !important;
    background-position: center !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    cursor: pointer !important;
    transition: transform 0.2s ease !important;
    -webkit-appearance: none !important;
    appearance: none !important;
    z-index: 10 !important;
    filter: brightness(1) saturate(1) !important; 
    -webkit-filter: brightness(1) saturate(1) !important;
    backdrop-filter: none !important;
    opacity: 1 !important;
    mix-blend-mode: normal !important;
    color: transparent !important; 
    overflow: visible !important; 
    margin-top: -9px !important; 
}
input[type="range"]::-webkit-slider-thumb:hover,
.neo-range-slider::-webkit-slider-thumb:hover,
.neo-range-slider .thumb:hover {
    transform: scale(1.2) !important;
}

/* Firefox 滑块手柄 */
input[type="range"]::-moz-range-thumb,
.neo-range-slider::-moz-range-thumb {
    width: var(--thumb-size) !important;
    height: var(--thumb-size) !important;
    background-image: url('https://i.postimg.cc/cCXxNGsp/IMG-1220.png') !important;
    background-color: transparent !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    cursor: pointer !important;
