/* 内部图片锁定比例，居中及向下偏移 */
.mes .avatar img {
    position: absolute !important;
    width: 74% !important;
    height: 74% !important;
    object-fit: cover !important; 
    border-radius: 50% !important;
    display: block !important;
    margin: 0 !important;
    padding: 0 !important;
    left: 50% !important;
