/* 底部信息胶囊整体 */
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    display: block !important; 
    font-size: 0.85rem !important;
    color: #84968c !important; 
    margin: 0 !important;
