.mes .mes_buttons .mes_edit { background-image: url('https://i.postimg.cc/d0hcr4YL/IMG-1206.png') !important; }


/* ===== 七、特殊文本修饰与推理/思考美化参 =====参考了墨千尾老师的拼好码css和nakari老师的自定义思维链文字 */
/* --- 1. Markdown 渲染定制 --- */
/* 星号包裹（斜体）：低饱和桃粉色 */
.mes_text em, .mes_text i {
    color: #d69fa8 !important;
    font-style: italic !important;
}
/* 引号包裹（引用）：瓷白毛玻璃 + 边框，防跨行断裂 */
.mes_text .quote, .mes_text q {
    display: inline !important;
    background: linear-gradient(to right, rgba(250, 252, 255, 0.95) 0%, rgba(250, 252, 255, 0.3) 100%) !important;
    border: 1px solid rgba(255, 255, 255, 0.8) !important;
    border-radius: 6px !important;
    padding: 2px 4px !important;
    line-height: 1.6 !important;
    -webkit-box-decoration-break: clone !important;
    box-decoration-break: clone !important;
}
/* 删除线：深胭脂红 */
.mes_text del, .mes_text s {
    text-decoration-line: line-through !important;
    text-decoration-color: #9b1e36 !important;
    color: #9b1e36 !important;
}
/* 下划线：嫩绿色 */
.mes_text u, .mes_text ins {
    text-decoration-line: underline !important;
    text-decoration-style: solid !important;
    text-decoration-color: #8db28d !important;
    text-decoration-thickness: 2px !important;
    text-underline-offset: 3px !important;
}
/* 波浪线：古风浅青色 */
.mes_text w, .mes_text .wavy {
    text-decoration-line: underline !important;
    text-decoration-style: wavy !important;
    text-decoration-color: #7ba29f !important;
    text-decoration-thickness: 2px !important;
    text-underline-offset: 3px !important;
}

/* --- 2. 引用块 (blockquote) 与 推理头 (mes_reasoning) --- */
.mes_text blockquote,
blockquote,
.mes_reasoning_header {
    background: linear-gradient(to right, rgba(250, 252, 255, 0.95) 0%, rgba(250, 252, 255, 0.3) 100%) !important;
    border: 1px solid rgba(255, 255, 255, 0.8) !important;
    border-radius: 8px !important;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.05) !important;
}
.mes_reasoning_summary {
    background: transparent !important;
    border: none !important;
}
/* 隐藏原生Thought文本，替换为古风定制--Nakari */
.mes_reasoning_header_title {
    color: transparent !important;
    font-size: 0px !important;
}
.mes_reasoning_header_title::before {
    content: "思忖中" !important;
    font-size: 1rem !important;
    color: rgba(104, 142, 133, 0.9) !important;
    font-family: "YFJLXS", sans-serif !important;
    letter-spacing: 2px !important;
    display: inline-block !important;
}


/* ===== 八、底部输入区与状态按钮极致美化 ===== */
