}

/* --- 3. 画船听雨眠 - 唯美提示词注入 ---参考了墨千尾老师输入框提示文字自定义 */
#send_textarea::placeholder {
    color: transparent !important;
    opacity: 0 !important;
}
#nonQRFormItems {
    position: relative !important;
}
#nonQRFormItems::after {
    content: "画船听雨眠" !important;
    position: absolute !important;
    left: 50% !important; 
    top: 50% !important;
    transform: translate(-50%, -50%) !important;
    color: rgba(104, 142, 133, 0.9) !important; 
    font-size: 1rem !important;
