}


/* ===== 九、全屏加载动画 (Preloader) ===== 参考serein老师的加载动画*/
/* 强行接管预加载容器背景，铺满瓷白全屏，粉碎所有框架限定 */
#bg_preloader { display: none !important; }
body #preloader, #preloader {
    position: fixed !important;
    top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    height: 100dvh !important;
    max-width: none !important;
    max-height: none !important;
    margin: 0 !important; padding: 0 !important;
    z-index: 999999 !important;
    background-image: none !important;
    background-color: #f8f9fa !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    transform: none !important;
    opacity: 1 !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}
@keyframes customSpin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}
/* 中心匀速旋转图标--Serein */
#load-spinner {
    --spinner-size: 120px;
    transition: none !important;
    opacity: 1 !important;
    top: calc(50% - 60px) !important;
    left: calc(50% - 60px) !important;
    position: absolute !important;
    width: var(--spinner-size) !important;
    height: var(--spinner-size) !important;
    background-image: url('https://i.postimg.cc/V6ZW6DHZ/IMG-1206.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    display: block !important;
    animation: customSpin 2s linear infinite !important;
    margin: 0 !important; padding: 0 !important;
    border: none !important;
    box-shadow: none !important;
    background-color: transparent !important;
}
#load-spinner::before, #load-spinner::after, #preloader * {
    display: none !important;
}


